# GF(2^128) multiply reference, polynomial x^128 + x^7 + x^2 + x + 1
def gf_mul(a, b):
    # a, b are 128-bit ints
    R = 0xE1000000000000000000000000000000  # reduction polynomial low 128 bits
    z = 0
    v = a
    for i in range(128):
        if (b >> i) & 1:
            z ^= v
        if v & 1:
            v = (v >> 1) ^ R
        else:
            v >>= 1
    return z

