#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <emmintrin.h>

#define N (256*1024*1024)  // 256MB
static unsigned char *a, *b;
static int nthreads;
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

void* read_worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / nthreads;
    size_t off = id*chunk;
    __m128i acc = _mm_setzero_si128();
    for(size_t j=0;j<chunk;j+=16) acc = _mm_add_epi8(acc, _mm_loadu_si128((__m128i*)(a+off+j)));
    volatile unsigned char sink = _mm_cvtsi128_si32(acc); (void)sink;
    return NULL;
}
void* write_worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / nthreads;
    size_t off = id*chunk;
    __m128i v = _mm_set1_epi8(0x5a);
    for(size_t j=0;j<chunk;j+=16) _mm_stream_si128((__m128i*)(b+off+j), v);
    return NULL;
}
void* copy_worker(void* arg){
    long id = (long)arg;
    size_t chunk = N / nthreads;
    size_t off = id*chunk;
    for(size_t j=0;j<chunk;j+=16){
        __m128i v = _mm_loadu_si128((__m128i*)(a+off+j));
        _mm_stream_si128((__m128i*)(b+off+j), v);
    }
    return NULL;
}
int main(int argc, char** argv){
    nthreads = argc>1?atoi(argv[1]):1;
    a = malloc(N); b = malloc(N);
    memset(a, 1, N); memset(b, 2, N);
    pthread_t th[64];
    int iters = 5;
    double gb = (double)N*iters/1e9;
    double t0,t1;
    t0=now();
    for(int r=0;r<iters;r++){
        for(long i=0;i<nthreads;i++) pthread_create(&th[i],NULL,read_worker,(void*)i);
        for(int i=0;i<nthreads;i++) pthread_join(th[i],NULL);
    }
    t1=now();
    printf("read  %2d threads: %.2f GB/s\n", nthreads, gb/(t1-t0));
    t0=now();
    for(int r=0;r<iters;r++){
        for(long i=0;i<nthreads;i++) pthread_create(&th[i],NULL,write_worker,(void*)i);
        for(int i=0;i<nthreads;i++) pthread_join(th[i],NULL);
    }
    t1=now();
    printf("write %2d threads: %.2f GB/s\n", nthreads, gb/(t1-t0));
    t0=now();
    for(int r=0;r<iters;r++){
        for(long i=0;i<nthreads;i++) pthread_create(&th[i],NULL,copy_worker,(void*)i);
        for(int i=0;i<nthreads;i++) pthread_join(th[i],NULL);
    }
    t1=now();
    printf("copy  %2d threads: %.2f GB/s (copy rate)\n", nthreads, gb/(t1-t0));
    return 0;
}
