#include <string.h>
#include <stdint.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>

static inline __m128i shl128(__m128i x, int k) {
    __m128i a = _mm_slli_epi64(x, k);
    __m128i b = _mm_srli_epi64(x, 64 - k);
    b = _mm_srli_si128(b, 8);
    return _mm_or_si128(a, b);
}

static inline __m128i gfmul(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i z3 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i mid = _mm_xor_si128(z2, z3);
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(mid, 8));
    __m128i hi = _mm_xor_si128(z1, _mm_srli_si128(mid, 8));
    uint64_t hi_hi = _mm_extract_epi64(hi, 1);
    uint64_t t = (hi_hi >> 57) ^ (hi_hi >> 62) ^ (hi_hi >> 63);
    __m128i r = lo;
    r = _mm_xor_si128(r, shl128(hi, 1));
    r = _mm_xor_si128(r, shl128(hi, 2));
    r = _mm_xor_si128(r, shl128(hi, 7));
    r = _mm_xor_si128(r, hi);
    r = _mm_xor_si128(r, _mm_set_epi64x(0, t << 1));
    r = _mm_xor_si128(r, _mm_set_epi64x(0, t << 2));
    r = _mm_xor_si128(r, _mm_set_epi64x(0, t << 7));
    r = _mm_xor_si128(r, _mm_set_epi64x(0, t));
    return r;
}

static void print128(const char* name, __m128i v) {
    unsigned char b[16];
    _mm_storeu_si128((__m128i*)b, v);
    printf("%s: ", name);
    for (int i=0;i<16;i++) printf("%02x", b[i]);
    printf("\n");
}

int main() {
    unsigned char hb[16] = {0xdb,0xf1,0x84,0x11,0x2e,0xb9,0x11,0x16,0x59,0x71,0x2b,0xaf,0xcf,0xf2,0xab,0x24};
    __m128i H = _mm_loadu_si128((__m128i*)hb);
    __m128i r = gfmul(H, H);
    print128("H*H", r);
    // expected: e92c1bd50adc79c6053c8a58fdfe9800
    return 0;
}
